export async function fixedHost(req) {
  return fetch(`https://example.com/users/${encodeURIComponent(req.query.user)}`, { redirect: 'error' });
}
export async function unknownRedirect(req) {
  return fetch(`https://example.com/users/${encodeURIComponent(req.query.user)}`);
}
export async function controlledOrigin(req) {
  return fetch(req.query.url);
}
